            </div>
          ))}
        </div>

        <button className="hero__nav hero__nav--next" onClick={nextSlide}>
          <ChevronRight />
        </button>

        <div className="hero__dots">
          {heroSlides.map((_, i) => (
            <button
              key={i}
              className={`hero__dot ${i === currentSlide ? 'hero__dot--active' : ''}`}
              onClick={() => setCurrentSlide(i)}
            />
          ))}
        </div>
      </div>
    </section>
  )
}

