  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
  margin-bottom: 16px;
}

.insights__card-title {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 20px;
}

.insights__cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 14px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.insights__cta:hover {
  border-color: var(--accent);
  color: var(--accent);
}

/* ==================== PRINCIPLES ==================== */
.principles {
  padding: 120px 40px;
  background: var(--bg-secondary);
}

.principles__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
  max-width: 1200px;
  margin: 0 auto;
}

.principles__card {
  padding: 32px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  transition: all var(--transition-fast);
}

.principles__card:hover {
  border-color: var(--accent);
}

.principles__number {
  display: block;
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 700;
  color: var(--accent);
  opacity: 0.3;
  margin-bottom: 16px;
}

.principles__title {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 600;
  margin-bottom: 12px;
}

.principles__desc {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ==================== FOOTER ==================== */
.footer {
  padding: 80px 40px 40px;
  background: var(--bg-primary);
  border-top: 1px solid var(--border);
}

.footer__cta {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
  max-width: 1000px;
  margin: 0 auto 64px;
}

.footer__cta-item {
  text-align: center;
  padding: 40px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
}

.footer__cta-item p {
  font-size: 18px;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

.footer__cta-item button {
  padding: 14px 28px;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  color: white;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.footer__cta-item button:hover {
  background: var(--accent-hover);
}

.footer__links {
  display: flex;
  justify-content: center;
  gap: 80px;
  max-width: 800px;
  margin: 0 auto 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid var(--border);
}

.footer__col h4 {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-primary);
  margin-bottom: 16px;
}

.footer__col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer__col a {
  font-size: 14px;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

.footer__col a:hover {
  color: var(--text-primary);
}

.footer__legal {
