  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
}

.cookie-consent__content {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.cookie-consent__content p {
  font-size: 14px;
  color: var(--text-secondary);
}

.cookie-consent__actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.cookie-consent__actions button {
  padding: 10px 20px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.cookie-consent__accept {
  background: var(--accent);
  border: none;
  color: white;
}

.cookie-consent__accept:hover {
  background: var(--accent-hover);
}

.cookie-consent__settings,
.cookie-consent__decline {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-secondary);
}

.cookie-consent__settings:hover,
.cookie-consent__decline:hover {
  border-color: var(--text-muted);
  color: var(--text-primary);
}

.cookie-consent__options {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  margin-top: 8px;
}

.cookie-consent__options label {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  color: var(--text-secondary);
  cursor: pointer;
}

.cookie-consent__options input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
}

/* ==================== RESPONSIVE ==================== */
@media (max-width: 1024px) {
  .nav__links {
    display: none;
  }

  .nav__mobile-toggle {
    display: flex;
  }

  .hero {
    padding: 100px 24px 60px;
  }

  .hero__nav--prev { left: 0; }
  .hero__nav--next { right: 0; }

  .team {
    padding: 80px 24px;
  }

  .team__card {
    flex: 0 0 100%;
    max-width: 500px;
    grid-template-columns: 1fr;
    text-align: center;
  }

  .team__card-image {
    width: 160px;
    height: 160px;
    margin: 0 auto;
  }

  .team__cta {
    align-self: center;
  }

  .work {
    padding: 80px 24px;
  }

  .work__card {
    flex: 0 0 320px;
  }

  .cta-banner,
  .how-we-work,
  .insights,
  .principles {
    padding: 80px 24px;
  }

  .footer__links {
    flex-direction: column;
    gap: 40px;
    text-align: center;
  }
}

@media (max-width: 768px) {
  .nav {
    padding: 16px 20px;
  }

  .hero__title {
    letter-spacing: -1px;
  }

  .hero__description {
    font-size: 16px;
  }

  .team__tabs {
    gap: 6px;
  }

  .team__tab {
    padding: 10px 16px;
    font-size: 13px;
  }

  .hero__slide {
    flex: 0 0 calc(33.333% - 16px);
    min-width: 120px;
  }

  .insights__grid,
  .principles__grid {
    grid-template-columns: 1fr;
  }

  .footer__legal {
    flex-direction: column;
    text-align: center;
  }

  .footer__legal-links {
    flex-wrap: wrap;
    justify-content: center;
  }

  .cookie-consent__actions {
    flex-direction: column;
  }

  .cookie-consent__actions button {
    width: 100%;
  }
}

@media (max-width: 480px) {
  .hero__slide {
    flex: 0 0 calc(50% - 8px);
  }

  .team__nav,
  .work__nav {
    display: none;
  }

  .hero__nav {
    display: none;
  }
}

/* ==================== ANIMATIONS ==================== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideIn {
  from { opacity: 0; transform: translateX(-20px); }
  to { opacity: 1; transform: translateX(0); }
}

.hero__content > * {
  animation: fadeIn 0.8s ease forwards;
}

.hero__content > *:nth-child(2) { animation-delay: 0.1s; }
.hero__content > *:nth-child(3) { animation-delay: 0.2s; }
.hero__content > *:nth-child(4) { animation-delay: 0.3s; }

/* Scroll animations */
@media (prefers-reduced-motion: no-preference) {
  .team__card,
  .work__card,
  .insights__card,
  .principles__card {
    animation: fadeIn 0.6s ease forwards;
  }
}

