  border: 1px solid rgba(59, 130, 246, 0.3);
  border-radius: 100px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
  margin-bottom: 24px;
}

.hero__title {
  font-family: var(--font-display);
  font-size: clamp(40px, 8vw, 80px);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -3px;
  margin-bottom: 24px;
  background: linear-gradient(180deg, var(--text-primary) 0%, var(--text-secondary) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero__description {
  font-size: 18px;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.hero__cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 16px 32px;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  color: white;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.hero__cta:hover {
  background: var(--accent-hover);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(59, 130, 246, 0.3);
}

/* Hero Carousel */
.hero__carousel {
  width: 100%;
  max-width: 1000px;
  position: relative;
}

.hero__slides {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 20px 0;
}

.hero__slides::-webkit-scrollbar {
  display: none;
}

.hero__slide {
  flex: 0 0 calc(20% - 16px);
  min-width: 160px;
  padding: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  scroll-snap-align: start;
  cursor: pointer;
  transition: all var(--transition-fast);
  opacity: 0.5;
}

.hero__slide:hover {
  opacity: 0.8;
  border-color: var(--text-muted);
}

.hero__slide--active {
  opacity: 1;
  border-color: var(--accent);
  background: rgba(59, 130, 246, 0.1);
}

.hero__slide-badge {
  display: block;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
  margin-bottom: 8px;
}

.hero__slide-title {
  display: block;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary);
  line-height: 1.4;
}

.hero__nav {
  position: absolute;
