  justify-content: center;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 50%;
  color: var(--text-primary);
  cursor: pointer;
  transition: all var(--transition-fast);
  z-index: 10;
}

.hero__nav:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-muted);
}

.hero__nav--prev { left: -24px; }
.hero__nav--next { right: -24px; }

.hero__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.hero__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.hero__dot:hover {
  background: var(--text-muted);
}

.hero__dot--active {
  background: var(--accent);
  width: 24px;
  border-radius: 4px;
}

/* ==================== TEAM SECTION ==================== */
.team {
  padding: 120px 40px;
  background: var(--bg-secondary);
}

.team__header {
  text-align: center;
  max-width: 600px;
  margin: 0 auto 48px;
}

.team__title {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 700;
  letter-spacing: -1px;
  margin-bottom: 16px;
}

.team__subtitle {
  font-size: 18px;
  color: var(--text-secondary);
}

.team__tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}

.team__tab {
  padding: 12px 24px;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 100px;
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
