  transform: scale(1);
}

.team__card-image {
  width: 200px;
  height: 200px;
  border-radius: 12px;
  overflow: hidden;
}

.team__card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.team__card-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.team__quote {
  font-size: 16px;
  font-style: italic;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 24px;
}

.team__name {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 600;
  margin-bottom: 4px;
}

.team__member-title {
  font-size: 14px;
  color: var(--accent);
  margin-bottom: 4px;
}

.team__office {
  font-size: 14px;
  color: var(--text-muted);
  margin-bottom: 20px;
}

.team__cta {
  display: inline-flex;
  align-self: flex-start;
  padding: 12px 20px;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text-primary);
  font-size: 14px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.team__cta:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.team__nav {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 50%;
  color: var(--text-primary);
  cursor: pointer;
  transition: all var(--transition-fast);
  flex-shrink: 0;
}

.team__nav:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-muted);
}

.team__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 32px;
}

.team__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.team__dot:hover {
  background: var(--text-muted);
}

.team__dot--active {
  background: var(--accent);
}

/* ==================== WORK SECTION ==================== */
.work {
  padding: 120px 40px;
  background: var(--bg-primary);
}

.work__header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 48px;
}

.work__title {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 700;
  letter-spacing: -1px;
  margin-bottom: 16px;
}

.work__subtitle {
  font-size: 18px;
  color: var(--text-secondary);
}

.work__carousel {
  position: relative;
  max-width: 1400px;
  margin: 0 auto;
}

.work__scroll {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 20px 40px;
}

.work__scroll::-webkit-scrollbar {
  display: none;
}

.work__card {
  flex: 0 0 400px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  scroll-snap-align: start;
  transition: all var(--transition-fast);
}

.work__card:hover {
  border-color: var(--text-muted);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.work__card-image {
  width: 100%;
  height: 240px;
  overflow: hidden;
}

.work__card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: grayscale(30%);
  transition: filter var(--transition-base);
}

.work__card:hover .work__card-image img {
  filter: grayscale(0%);
}

.work__card-content {
  padding: 24px;
}

.work__client {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
}

.work__card-title {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  margin: 8px 0 12px;
  line-height: 1.3;
}

.work__card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

.work__testimonial {
  font-size: 13px;
  font-style: italic;
  color: var(--text-muted);
  border-left: 2px solid var(--accent);
  padding-left: 12px;
  margin-top: 16px;
}

.work__testimonial cite {
  display: block;
  margin-top: 4px;
  font-style: normal;
  color: var(--text-secondary);
}

.work__nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 50%;
  color: var(--text-primary);
  cursor: pointer;
  transition: all var(--transition-fast);
  z-index: 10;
}

.work__nav:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-muted);
}

.work__nav--left { left: 0; }
.work__nav--right { right: 0; }

/* ==================== CTA BANNER ==================== */
.cta-banner {
  padding: 100px 40px;
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.1) 0%, rgba(245, 158, 11, 0.05) 100%);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.cta-banner__content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.cta-banner__title {
  font-family: var(--font-display);
  font-size: clamp(36px, 6vw, 56px);
  font-weight: 700;
  letter-spacing: -2px;
  margin-bottom: 20px;
}

.cta-banner__text {
  font-size: 18px;
  color: var(--text-secondary);
  margin-bottom: 32px;
  line-height: 1.7;
}

.cta-banner__cta {
  display: inline-flex;
  padding: 16px 40px;
  background: var(--text-primary);
  border: none;
  border-radius: 8px;
  color: var(--bg-primary);
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.cta-banner__cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(255, 255, 255, 0.2);
}

/* ==================== HOW WE WORK ==================== */
.how-we-work {
  padding: 120px 40px;
  background: var(--bg-secondary);
}

.how-we-work__content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.how-we-work__title {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 700;
  letter-spacing: -1px;
  margin-bottom: 24px;
}

.how-we-work__text {
  font-size: 18px;
  color: var(--text-secondary);
  line-height: 1.8;
  margin-bottom: 32px;
}

.how-we-work__cta {
  display: inline-flex;
  padding: 14px 28px;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text-primary);
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.how-we-work__cta:hover {
  border-color: var(--accent);
  color: var(--accent);
}

/* ==================== INSIGHTS ==================== */
.insights {
  padding: 120px 40px;
  background: var(--bg-primary);
}

.insights__header {
  text-align: center;
  max-width: 600px;
  margin: 0 auto 64px;
}

.insights__title {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 700;
  letter-spacing: -1px;
  margin-bottom: 16px;
}

.insights__subtitle {
  font-size: 18px;
  color: var(--text-secondary);
}

.insights__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
  max-width: 1200px;
  margin: 0 auto;
}

.insights__card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 28px;
  transition: all var(--transition-fast);
}

.insights__card:hover {
  border-color: var(--text-muted);
  transform: translateY(-2px);
}

.insights__type {
  display: inline-block;
  padding: 4px 10px;
  background: rgba(59, 130, 246, 0.1);
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
  margin-bottom: 16px;
}

.insights__card-title {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 20px;
}

.insights__cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 14px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.insights__cta:hover {
  border-color: var(--accent);
  color: var(--accent);
}

/* ==================== PRINCIPLES ==================== */
.principles {
  padding: 120px 40px;
  background: var(--bg-secondary);
}

.principles__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
  max-width: 1200px;
  margin: 0 auto;
}

.principles__card {
  padding: 32px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  transition: all var(--transition-fast);
}

.principles__card:hover {
  border-color: var(--accent);
}

.principles__number {
  display: block;
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 700;
  color: var(--accent);
  opacity: 0.3;
  margin-bottom: 16px;
}

.principles__title {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 600;
  margin-bottom: 12px;
}

.principles__desc {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ==================== FOOTER ==================== */
.footer {
  padding: 80px 40px 40px;
  background: var(--bg-primary);
  border-top: 1px solid var(--border);
}

.footer__cta {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
  max-width: 1000px;
  margin: 0 auto 64px;
}

.footer__cta-item {
  text-align: center;
  padding: 40px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
}

.footer__cta-item p {
  font-size: 18px;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

.footer__cta-item button {
  padding: 14px 28px;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  color: white;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.footer__cta-item button:hover {
  background: var(--accent-hover);
}

.footer__links {
  display: flex;
  justify-content: center;
  gap: 80px;
  max-width: 800px;
  margin: 0 auto 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid var(--border);
}

.footer__col h4 {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-primary);
  margin-bottom: 16px;
}

.footer__col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer__col a {
  font-size: 14px;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

.footer__col a:hover {
  color: var(--text-primary);
}

.footer__legal {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  max-width: 1200px;
  margin: 0 auto;
}

.footer__legal p {
  font-size: 13px;
  color: var(--text-muted);
}

.footer__legal-links {
  display: flex;
  gap: 24px;
}

.footer__legal-links a {
  font-size: 13px;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

.footer__legal-links a:hover {
  color: var(--text-primary);
}

/* ==================== COOKIE CONSENT ==================== */
.cookie-consent {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  padding: 20px;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
}

.cookie-consent__content {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.cookie-consent__content p {
  font-size: 14px;
  color: var(--text-secondary);
}

.cookie-consent__actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.cookie-consent__actions button {
  padding: 10px 20px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.cookie-consent__accept {
  background: var(--accent);
  border: none;
  color: white;
}

.cookie-consent__accept:hover {
  background: var(--accent-hover);
}

.cookie-consent__settings,
.cookie-consent__decline {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-secondary);
}

.cookie-consent__settings:hover,
.cookie-consent__decline:hover {
  border-color: var(--text-muted);
  color: var(--text-primary);
}

.cookie-consent__options {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  margin-top: 8px;
}

.cookie-consent__options label {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  color: var(--text-secondary);
  cursor: pointer;
}

.cookie-consent__options input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
}

/* ==================== RESPONSIVE ==================== */
@media (max-width: 1024px) {
  .nav__links {
    display: none;
  }

  .nav__mobile-toggle {
    display: flex;
  }

  .hero {
    padding: 100px 24px 60px;
  }

  .hero__nav--prev { left: 0; }
  .hero__nav--next { right: 0; }

  .team {
    padding: 80px 24px;
  }

  .team__card {
    flex: 0 0 100%;
    max-width: 500px;
    grid-template-columns: 1fr;
    text-align: center;
  }

  .team__card-image {
    width: 160px;
    height: 160px;
    margin: 0 auto;
  }

  .team__cta {
    align-self: center;
  }

  .work {
    padding: 80px 24px;
  }

  .work__card {
    flex: 0 0 320px;
  }

  .cta-banner,
  .how-we-work,
  .insights,
  .principles {
    padding: 80px 24px;
  }

  .footer__links {
    flex-direction: column;
    gap: 40px;
    text-align: center;
  }
}

@media (max-width: 768px) {
  .nav {
    padding: 16px 20px;
  }

  .hero__title {
    letter-spacing: -1px;
  }

  .hero__description {
    font-size: 16px;
  }

  .team__tabs {
    gap: 6px;
  }

  .team__tab {
    padding: 10px 16px;
    font-size: 13px;
  }

  .hero__slide {
    flex: 0 0 calc(33.333% - 16px);
    min-width: 120px;
  }

  .insights__grid,
  .principles__grid {
    grid-template-columns: 1fr;
  }

  .footer__legal {
    flex-direction: column;
    text-align: center;
  }

  .footer__legal-links {
    flex-wrap: wrap;
    justify-content: center;
  }

  .cookie-consent__actions {
    flex-direction: column;
  }

  .cookie-consent__actions button {
    width: 100%;
  }
}

@media (max-width: 480px) {
  .hero__slide {
    flex: 0 0 calc(50% - 8px);
  }

  .team__nav,
  .work__nav {
    display: none;
  }

  .hero__nav {
    display: none;
  }
}

/* ==================== ANIMATIONS ==================== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideIn {
  from { opacity: 0; transform: translateX(-20px); }
  to { opacity: 1; transform: translateX(0); }
}

.hero__content > * {
  animation: fadeIn 0.8s ease forwards;
}

.hero__content > *:nth-child(2) { animation-delay: 0.1s; }
.hero__content > *:nth-child(3) { animation-delay: 0.2s; }
.hero__content > *:nth-child(4) { animation-delay: 0.3s; }

/* Scroll animations */
@media (prefers-reduced-motion: no-preference) {
  .team__card,
  .work__card,
  .insights__card,
  .principles__card {
    animation: fadeIn 0.6s ease forwards;
  }
}
