  margin-bottom: 20px;
}

.team__cta {
  display: inline-flex;
  align-self: flex-start;
  padding: 12px 20px;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text-primary);
  font-size: 14px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.team__cta:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.team__nav {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 50%;
  color: var(--text-primary);
  cursor: pointer;
  transition: all var(--transition-fast);
  flex-shrink: 0;
}

.team__nav:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-muted);
}

.team__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 32px;
}

.team__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.team__dot:hover {
  background: var(--text-muted);
}

.team__dot--active {
  background: var(--accent);
}

/* ==================== WORK SECTION ==================== */
.work {
  padding: 120px 40px;
  background: var(--bg-primary);
}

.work__header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 48px;
}

.work__title {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 700;
  letter-spacing: -1px;
  margin-bottom: 16px;
}

.work__subtitle {
  font-size: 18px;
  color: var(--text-secondary);
}

.work__carousel {
  position: relative;
  max-width: 1400px;
  margin: 0 auto;
}

.work__scroll {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 20px 40px;
}

.work__scroll::-webkit-scrollbar {
  display: none;
}

.work__card {
  flex: 0 0 400px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
