  color: var(--accent);
}

.work__card-title {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  margin: 8px 0 12px;
  line-height: 1.3;
}

.work__card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

.work__testimonial {
