  border-bottom: 1px solid var(--border);
}

.cta-banner__content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.cta-banner__title {
  font-family: var(--font-display);
  font-size: clamp(36px, 6vw, 56px);
  font-weight: 700;
  letter-spacing: -2px;
  margin-bottom: 20px;
}

.cta-banner__text {
  font-size: 18px;
  color: var(--text-secondary);
  margin-bottom: 32px;
  line-height: 1.7;
}

.cta-banner__cta {
  display: inline-flex;
  padding: 16px 40px;
  background: var(--text-primary);
